import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';
import { SeoMetadata } from './seo.service';

interface PageSeoApiItem {
	page_name?: string;
	meta_title?: string;
	meta_description?: string;
	meta_keywords?: string;
}

interface PageSeoApiResponse {
	code?: number;
	result?: PageSeoApiItem | PageSeoApiItem[];
}

@Injectable({
	providedIn: 'root'
})
export class PageSeoService {
	private readonly endpoint = `${environment.baseUrl}/api/page/getpagewithName`;

	constructor(
		private readonly http: HttpClient,
		private readonly transferState: TransferState,
		@Inject(PLATFORM_ID) private readonly platformId: Object
	) { }

	getPageSeo(pageName: string): Observable<SeoMetadata | null> {
		const stateKey = makeStateKey<SeoMetadata | null>(`page-seo:${pageName}`);

		if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
			const cachedSeo = this.transferState.get<SeoMetadata | null>(stateKey, null);
			this.transferState.remove(stateKey);
			return of(cachedSeo);
		}

		return this.http.post<PageSeoApiResponse>(this.endpoint, { pageName }).pipe(
			map((response) => this.mapResponseToSeo(response)),
			tap((seo) => {
				if (isPlatformServer(this.platformId)) {
					this.transferState.set(stateKey, seo);
				}
			}),
			catchError((error) => {
				console.warn(`PageSeoService: failed to load SEO for "${pageName}"`, error?.error?.message ?? error?.message);
				return of(null);
			})
		);
	}

	private mapResponseToSeo(response: PageSeoApiResponse): SeoMetadata | null {
		const page = Array.isArray(response?.result) ? response.result[0] : response?.result;
		if (!page) {
			return null;
		}

		return {
			title: page.meta_title?.trim(),
			description: page.meta_description?.trim(),
			keywords: page.meta_keywords?.trim()
		};
	}
}
